async function openCatalog(){
 if($('rsAssetCatalog')){$('rsAssetCatalog').focus();return}
 const project=pid,context=projectSession.context;const response=await api('/api/materials');catalog=response.materials;let dirty=false;
 const d=document.createElement('dialog');d.id='rsAssetCatalog';d.className='winDlg';d.style='width:min(1100px,95vw);max-height:92vh;overflow:auto';
 d.innerHTML='<header class="row"><h2 class="grow">Materiais, símbolos e nomes CAD</h2><button type="button" data-close aria-label="Fechar catálogo">×</button></header><p>Texturas locais e dimensões ilustrativas. Confira a classe e o material antes de calcular.</p><label>Buscar material<input id="rsAssetSearch" placeholder="Gás, ferrovia, erosão, torre…"></label><div id="rsAssetGallery" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px"></div><hr><h3>Cadastrar outros nomes</h3><label>Nome do perfil reutilizável<input id="rsAssetProfile" maxlength="80" placeholder="Padrão da empresa"></label><div class="grid"><label>Nome ou padrão do DXF<input id="rsAssetPattern" maxlength="200" placeholder="*NOME_DA_CAMADA*"></label><label>Classe<select id="rsAssetRole"></select></label><label>Material<select id="rsAssetMaterial"></select></label></div><button type="button" id="rsAssetAdd">Adicionar regra</button><ul id="rsAssetRules"></ul><p id="rsAssetError" role="alert"></p><footer class="row"><button type="button" id="rsAssetDefault">Reconhecer nomes do DXF</button><button type="button" id="rsAssetSave">Salvar perfil</button><button type="button" id="rsAssetApply">Salvar e aplicar no projeto</button><button type="button" data-close>Fechar</button></footer>';
 document.body.appendChild(d);const header=d.querySelector('header'),footer=d.querySelector('footer'),body=document.createElement('div');body.style='overflow:auto;min-height:0;flex:1;padding:10px 0';for(const node of [...d.childNodes])if(node!==header&&node!==footer)body.appendChild(node);header.after(body);d.style.display='flex';d.style.flexDirection='column';d.style.height='min(840px,92vh)';d.style.overflow='hidden';header.style='flex:none;border-bottom:1px solid #ccc';footer.style='flex:none;border-top:1px solid #ccc;padding-top:10px';const additions=[];
 $('rsAssetRole').innerHTML=Object.entries(roles).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('');
 const materials=()=>{const role=$('rsAssetRole').value;const rows=catalog.filter(m=>m.role===role);$('rsAssetMaterial').innerHTML='<option value="">Material padrão da classe</option>'+rows.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')};
 $('rsAssetRole').onchange=materials;materials();
 const searchKey=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
 const gallery=()=>{const q=searchKey($('rsAssetSearch').value.trim());$('rsAssetGallery').innerHTML=catalog.filter(m=>searchKey(m.name+' '+m.aliases.join(' ')).includes(q)).map(m=>`<button type="button" data-material="${m.id}" title="Selecionar ${esc(m.name)}"><img src="/api/materials/${m.id}.png" alt="${esc(m.name)}" width="96" height="72"><br>${RodoviaInfraRail.forMaterial(m.role)}${esc(m.name)}</button>`).join('')};
 $('rsAssetSearch').oninput=gallery;gallery();
 d.addEventListener('click',e=>{const key=e.target.closest('[data-material]')?.dataset.material;if(key){const row=catalog.find(m=>m.id===key);$('rsAssetRole').value=row.role;materials();$('rsAssetMaterial').value=row.id;dirty=true}});
 d.addEventListener('input',e=>{if(e.target.id!=='rsAssetSearch')dirty=true});
 $('rsAssetAdd').onclick=()=>{const pattern=$('rsAssetPattern').value.trim();if(!pattern){$('rsAssetError').textContent='Informe o nome ou padrão da camada.';return}additions.push({pattern,role:$('rsAssetRole').value,...($('rsAssetMaterial').value?{material:$('rsAssetMaterial').value}:{})});dirty=true;$('rsAssetPattern').value='';$('rsAssetRules').innerHTML=additions.map((r,i)=>`<li>${esc(r.pattern)} → ${esc(roles[r.role])}${r.material?' · '+esc(catalog.find(m=>m.id===r.material)?.name||''):''} <button type="button" data-remove-rule="${i}" aria-label="Remover regra">×</button></li>`).join('')};
 d.addEventListener('click',e=>{const raw=e.target.closest('[data-remove-rule]')?.dataset.removeRule;if(raw===undefined)return;additions.splice(Number(raw),1);e.target.closest('li').remove();[...d.querySelectorAll('[data-remove-rule]')].forEach((b,i)=>b.dataset.removeRule=i);dirty=true});
 async function saveProfile(apply=false){
  if($('rsAssetPattern').value.trim())$('rsAssetAdd').click();
  const name=$('rsAssetProfile').value.trim();if(!name||!additions.length)throw Error('Informe o nome do perfil e adicione pelo menos uma regra.');
  const builtin=(await api('/api/layer_profiles')).profiles.find(p=>p.builtin);await api('/api/layer_profiles',json('POST',{name,rules:[...additions,...(builtin?.rules||[])]}));await loadProfiles();$('layerProfile').value=name;
  if(apply){requireProject();if(pid!==project||projectSession.context!==context)throw Error('O projeto mudou; reabra o cadastro antes de aplicar.');const mapped=await api(`/api/projects/${pid}/layer_profiles/apply`,json('POST',{name}));if(pid!==project||projectSession.context!==context)throw Error('O projeto mudou durante a aplicação.');if(!mapped.total)throw Error('Importe um DXF antes de aplicar nomes no projeto.');checkpointLayers();const layers=structuredClone(cfg.layers||{});for(const [role,names] of Object.entries(mapped.layers))for(const name of names){for(const key of Object.keys(layers))layers[key]=layers[key].filter(n=>n!==name);(layers[role]??=[]).push(name)}cfg.layers=layers;cfg.layer_materials={...(cfg.layer_materials||{}),...(mapped.materials||{})};showLayers();scheduleSave()}
  dirty=false;window.RodoviaUpdatePolicy?.committed({project,context});msg(apply?'Perfil aplicado. Confira as camadas e recalcule os fluxos.':'Perfil salvo para reutilizar em outros projetos.');return true;
 }
 async function performSave(apply){try{$('rsAssetError').textContent='';await saveProfile(apply)}catch(e){$('rsAssetError').textContent=e.message;$('rsAssetError').scrollIntoView({block:'nearest'})}}
 $('rsAssetDefault').onclick=guard(async()=>{requireProject();if(pid!==project||projectSession.context!==context)throw Error('O projeto mudou; reabra o catálogo.');const data=await api('/api/layer_profiles'),standard=data.profiles.find(p=>p.builtin),mapped=await api(`/api/projects/${pid}/layer_profiles/apply`,json('POST',{name:standard.name}));if(pid!==project||projectSession.context!==context)throw Error('O projeto mudou durante a leitura.');if(!mapped.total)throw Error('Importe um DXF antes de reconhecer os nomes.');checkpointLayers();const layers=structuredClone(cfg.layers||{}),assigned=new Set(Object.values(layers).flat());let count=0;for(const [role,names] of Object.entries(mapped.layers))for(const name of names)if(!assigned.has(name)){(layers[role]??=[]).push(name);count++}cfg.layers=layers;cfg.layer_materials={...(cfg.layer_materials||{}),...(mapped.materials||{})};showLayers();scheduleSave();$('rsAssetError').textContent=count+' nova(s) camada(s) reconhecida(s). As classificações existentes foram preservadas. Feche e recalcule os fluxos.'});
 $('rsAssetSave').onclick=()=>void performSave(false);$('rsAssetApply').onclick=()=>void performSave(true);
 function finish(){d.close();d.remove()}
 async function close(){if(!dirty){finish();return}const ask=document.createElement('dialog');ask.className='winDlg';ask.innerHTML='<h3>Salvar alterações do cadastro?</h3><p role="alert"></p><div class="row"><button data-choice="continue">Continuar editando</button><button data-choice="discard">Descartar</button><button data-choice="save">Salvar perfil</button></div>';document.body.appendChild(ask);ask.onclick=guard(async e=>{const choice=e.target.closest('[data-choice]')?.dataset.choice;if(!choice)return;if(choice==='save')try{await saveProfile(false)}catch(error){ask.querySelector('[role=alert]').textContent=error.message;return}ask.close();ask.remove();if(choice!=='continue')finish()});ask.oncancel=e=>{e.preventDefault();ask.close();ask.remove()};ask.showModal()}
 d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>void close());d.addEventListener('cancel',e=>{e.preventDefault();void close()});d.showModal();
}

