async function open(){
 requireProject();if(!editor?.segments?.length){if(!await closePanels())return;if(await start('analyze')===false)return;}
 if(dialog?.open)return;dialog=document.createElement('dialog');dialog.className='winDlg rsFlowRepairDialog';dialog.style.width='min(1000px,94vw)';dialog.style.maxWidth='1000px';dialog.style.maxHeight='85vh';dialog.style.overflow='auto';dialog.setAttribute('aria-label','Corrigir fluxos');
 dialog.innerHTML='<h3>Corrigir fluxos</h3><p>Linhas de bordo, marcações e linhas perpendiculares de referência não são barreiras. Se uma camada foi interpretada incorretamente, corrija seu tipo em Camadas e recalcule. Não é necessário refazer o projeto.</p><p><b>Proteções mantidas:</b> barreiras/canteiros físicos, colisões, sinal vermelho e interdições com pare e siga. Curvas impossíveis e coordenadas inválidas também precisam ser corrigidas.</p><div class="row"><button data-global="sections">Montar seção típica de fluxo</button><button data-global="layers">Revisar camadas que bloqueiam</button><button data-global="calculate">Recalcular fluxos</button><button data-global="criteria">Revisar critério automático de canteiro</button><button data-global="select">Selecionar fluxo em tela</button><button data-global="close">Fechar</button></div><p>Reconstruir tenta suavizar a ligação preservando início, fim e progressão, com desvio máximo de 8 m e conferência física. Barreiras, cortes explícitos e sentidos não são suspensos. Recuperar exclui somente partes reprovadas e revalida o restante. Recortar permite marcar início e fim do defeito. Ajustes automáticos de afastamento não movem o eixo DXF.</p><div data-flow-results></div>';
 const restrictive=document.createElement('p');const names=Object.keys(cfg.layers||{}).length?['barrier','median'].flatMap(role=>(cfg.layers[role]||[]).map(name=>name+' ('+(role==='barrier'?'barreira':'canteiro')+')')):(analysis?.layers||[]).filter(l=>['barrier','median'].includes(l.suggested_role)).map(l=>l.name+' (sugestão)');restrictive.textContent='Camadas restritivas cadastradas/sugeridas: '+(names.join(', ')||'nenhuma listada; confira também as áreas desenhadas e proibições manuais.');dialog.querySelector('[data-flow-results]').appendChild(restrictive);
 const gaps=(editor.section_continuity||[]).flatMap(route=>(route.gaps||[]).map(gap=>route.name+': '+Number(gap.start_m).toFixed(1)+' a '+Number(gap.end_m).toFixed(1)+' m'));if(gaps.length){const warning=document.createElement('p');warning.className='rsSectionGaps';warning.textContent='Intervalos sem seção cadastrada (não preenchidos automaticamente): '+gaps.slice(0,30).join('; ')+'. Use Montar seção típica para conferir e editar os limites.';dialog.querySelector('[data-flow-results]').appendChild(warning)}
 const rows=document.createElement('div');const segments=[...(editor?.segments||[])].sort((a,b)=>(a.technical_status==='ok')-(b.technical_status==='ok'));
 if(!segments.length){const p=document.createElement('p');p.textContent='Nenhuma trajetória foi criada. Use Revisar camadas: designe a camada Eixo e a área fechada de pavimento, ou selecione uma linha explicitamente como rota e indique o sentido. Depois recalcule. A densidade só controla veículos em trajetórias válidas.';rows.appendChild(p)}
 for(const s of segments.slice(0,300)){
  const row=document.createElement('section');row.style.padding='10px';row.style.marginBottom='8px';row.dataset.flowRepair=String(s.id);
  const heading=document.createElement('b');heading.textContent=(s.route_name||s.source||'Fluxo')+' · '+s.id+' · '+({ok:'OK',problem:'Bloqueado',adjustment:'Revisar'}[s.technical_status]||'Revisar');row.appendChild(heading);
  const text=document.createElement('p');text.textContent=s.technical_message||'Recalcule para obter um diagnóstico atualizado.';row.appendChild(text);
  if(s.technical_lateral_fits?.length){const fit=document.createElement('p');fit.textContent=s.technical_lateral_fits.map(f=>'Afastamento: '+f.original_m+' → '+f.applied_m+' m.').join(' ');row.appendChild(fit)}
  if(s.technical_assistant){const why=document.createElement('p');why.textContent=s.technical_assistant.title;row.appendChild(why)}
  if(s.technical_circulation){const info=document.createElement('p');info.className='muted';info.textContent=s.technical_circulation.enabled?'Há circulação em trajetórias aprovadas; partes excluídas permanecem fora da simulação.':'Sem circulação neste resultado. Confira o motivo antes de alterar o traçado.';row.appendChild(info)}
  const buttons=document.createElement('div');buttons.className='row';
  const add=(target,kind,label)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.repairAction=kind;b.onclick=guard(()=>action(s.id,kind));if(['auto','recover','reconstruct'].includes(kind)&&(s.disabled||s.technical_status==='ok')){b.disabled=true;b.title=s.disabled?'Desligamento manual preservado.':'Este fluxo já está validado.'}target.appendChild(b)};
  for(const [kind,label] of [['locate','Localizar'],['auto','Tentar correção automática'],['properties','Editar manualmente']])add(buttons,kind,label);row.appendChild(buttons);
  const advanced=document.createElement('details');advanced.className='rsFlowRepairAdvanced';advanced.innerHTML='<summary>Opções avançadas de recuperação</summary>';const extra=document.createElement('div');extra.className='row';
  for(const [kind,label] of [['reconstruct','Reconstruir ligação contínua'],['recover','Recuperar partes válidas'],['cut','Recortar início/fim']])add(extra,kind,label);advanced.appendChild(extra);row.appendChild(advanced);rows.appendChild(row);

 }
 if(segments.length>300){const p=document.createElement('p');p.textContent='Mostrando os primeiros 300 trechos, com problemas primeiro. Use a seleção em tela para os demais.';rows.appendChild(p)}
 dialog.querySelector('[data-flow-results]').appendChild(rows);
 dialog.addEventListener('click',guard(async e=>{const kind=e.target.closest('[data-global]')?.dataset.global;if(!kind)return;close();if(kind==='close')return;if(!await closePanels())return;if(kind==='criteria'){const d=document.createElement('dialog');d.className='winDlg';d.innerHTML='<h3>Critério automático de canteiro</h3><p>A proximidade de eixos pode sugerir uma troca de pista inexistente. Suspender essa inferência não remove barreiras ou canteiros físicos, proibições manuais, colisões, sinais nem pare e siga.</p><div class="row"><button data-mode="free">Suspender inferência e recalcular</button><button data-mode="returns">Restaurar critério e recalcular</button><button data-cancel>Cancelar</button></div>';document.body.appendChild(d);d.onclick=guard(async e=>{if(e.target.closest('[data-cancel]')){d.close();d.remove();return}const mode=e.target.closest('[data-mode]')?.dataset.mode;if(!mode)return;checkpoint();$('median_crossing').value=mode;cfg.median_crossing=mode;changed('Critério automático de canteiro ajustado; proteções físicas mantidas.');d.close();d.remove();await start('analyze')});d.oncancel=()=>d.remove();d.showModal();}else if(kind==='sections'){await RodoviaSections.chooseAxis();}else if(kind==='layers'){psOpenHub('layers');msg('Confira as camadas classificadas como Barreira e Canteiro. Para referências e bordos, escolha o tipo correto. Recalcule após salvar.');}else if(kind==='calculate')await start('analyze');else{vecOn.flows=true;if(window.RodoviaFlowStudy)RodoviaFlowStudy.editing=true;selSeg=null;setTool('pan');draw();msg('Clique sobre uma trajetória para editar; utilize Localizar defeito na central se não conseguir selecioná-la.');}}));
 dialog.addEventListener('cancel',e=>{e.preventDefault();close()});document.body.appendChild(dialog);dialog.showModal();
}

async function execution({segment=null}={}){requireProject();if(window.RodoviaPanels&&!await RodoviaPanels.close())return;await save();const project=pid,context=projectSession.context,d=dialog('IA assistida — resolver fluxos'),body=el('div'),info=el('p','Aplicativo fornece dados → regras propõem → motor executa e revalida.');d.insertBefore(info,d.lastElementChild);d.insertBefore(body,d.lastElementChild);let data=null;
 const alive=()=>{if(pid!==project||projectSession.context!==context||!d.isConnected)throw Error('O projeto mudou. Reabra a assistência.')};
 async function read(){alive();body.replaceChildren();try{data=await api('/api/projects/'+project+'/assistencia/execucao')}catch(e){body.append(el('p',e.message));button(body,'Atualizar diagnóstico',async()=>{d.close();try{await start('refresh');alive();d.showModal();await read()}catch(e){if(d.isConnected&&!d.open)d.showModal();throw e}});return}
 const excluded=data.segments.filter(s=>s.technical_exclusion==='length_limit');if(excluded.length)body.append(el('p',excluded.length+' rota(s) desligada(s) pelo limite de comprimento do projeto. Não são defeitos a liberar; a geometria original está preservada.'));
 const issues=data.segments.filter(s=>s.technical_status!=='ok'&&s.technical_exclusion!=='length_limit').sort((a,b)=>Number(b.id===segment)-Number(a.id===segment));if(!issues.length)body.append(el('p','Nenhum conflito no diagnóstico atual. Isso não certifica ausência universal de falhas.'));
 for(const s of issues.slice(0,100)){const row=el('section');row.append(el('h3',(s.source||'Fluxo')+' · '+s.id),el('p',s.technical_message));if(s.technical_assistant)row.append(el('p',s.technical_assistant.title));const actions=el('div');actions.className='row';
 button(actions,'Localizar',()=>{d.close();selSeg={id:s.id};vecOn.flows=true;RodoviaFlowStudy.editing=true;setTool('pan');zoomTo(P(s.technical_points?.[0]?.point||s.mid));draw();msg(s.technical_message);$('rsReturnExecution')?.remove();const reopen=el('button','Voltar à assistência');reopen.id='rsReturnExecution';reopen.onclick=()=>{reopen.remove();try{alive();d.showModal()}catch(e){d.remove();msg(e.message,true)}};$('rsQuickNavigation').append(reopen)});
 const propose=button(actions,'Analisar e propor correção',async()=>{alive();d.close();try{const result=await start('assisted_plan',{segment:s.id,action:'auto',signature:data.signature});alive();d.showModal();if(!result||result.state!=='done')return;const plan=await api('/api/projects/'+project+'/assistencia/execucao/proposta');showPlan(plan)}catch(e){if(d.isConnected&&!d.open)d.showModal();throw e}});propose.disabled=!!s.disabled;
 button(actions,'Editar manualmente',()=>{d.close();d.remove();selSeg={id:s.id};showSegProps()});row.append(actions);body.append(row)}
 }
 function showPlan(plan){body.replaceChildren();body.append(el('h3','Prévia da ação: '+({recover:'Recuperar partes válidas',reconstruct:'Reconstrução validada'}[plan.action]||plan.action)),el('p',plan.before.message));for(const r of plan.after)body.append(el('p','Depois: '+r.message));body.append(el('p','Cinza: trecho original. Verde: trajetórias revalidadas pelo motor, incluindo ligações necessárias.'));plot(body,plan.before.geometry,plan.geometry);body.append(el('p',plan.notice));if(!plan.can_apply)body.append(el('p','Não há alteração segura aprovada. Edite a seção, as camadas ou os pontos; nenhuma restrição foi suspensa.'));
 const apply=button(body,'Confirmar e aplicar correção',async()=>{alive();apply.disabled=true;await api('/api/projects/'+project+'/assistencia/execucao/'+plan.id+'/aplicar',{method:'POST'});info.textContent='Correção aplicada; revalidação pendente.';await load(project,{resultsOnly:true,syncConfig:true});button(body,'Desfazer correção',async()=>{alive();await api('/api/projects/'+project+'/assistencia/execucao/'+plan.id+'/desfazer',{method:'POST'});await load(project,{resultsOnly:true,syncConfig:true});info.textContent='Correção desfeita. Atualização pendente.';await read()});
 button(body,'Revalidar resultado',async()=>{alive();d.close();try{await start('refresh');alive();d.showModal();const outcome=await api('/api/projects/'+project+'/assistencia/execucao/'+plan.id+'/resultado');info.textContent=outcome.resolved?'Conflito resolvido na revalidação desta revisão.':'Correção aplicada com pendências; confira o diagnóstico e edite manualmente.';for(const s of outcome.segments)body.append(el('p',s.message))}catch(e){if(d.isConnected&&!d.open)d.showModal();throw e}});
 });apply.disabled=!plan.can_apply;button(body,'Voltar ao diagnóstico',read);
 }
 await read();
}

async function open(){
 requireProject();if(!await RodoviaPanels.close())return;await save();
 const project=pid,context=projectSession.context,d=el('dialog');d.className='winDlg rsTrafficHelp';d.setAttribute('aria-label','Diagnosticar veículos');d.append(el('h2','Por que os veículos não aparecem?'));
 const info=el('div'),error=el('p');error.setAttribute('role','alert');const row=el('div');row.className='row';d.append(info,error,row);document.body.append(d);
 const alive=()=>d.isConnected&&project===pid&&context===projectSession.context;
 let data=null,busy=false;
 async function read(){data=await api('/api/projects/'+project+'/traffic_status');if(!alive())return;info.replaceChildren(el('p','Veículos: '+(data.enabled?'ativados':'desativados')+' · itinerários válidos: '+(data.itineraries??'diagnóstico pendente')),
 el('p','Gerados na simulação: '+(data.simulated_vehicles??'ainda não medido')+' · ativos na prévia: '+(data.preview_active??'ainda não medido')+' · desenhados na prévia: '+(data.preview_drawn??'ainda não medido')));
 for(const note of data.notices)info.append(el('p',note));for(const s of data.segments.slice(0,12))info.append(el('p',(s.source||'Fluxo')+': '+s.technical_message));info.append(el('small',data.scope));focus.disabled=!data.editor_current||!data.itineraries}
 function button(text,fn){const b=el('button',text);b.type='button';b.onclick=guard(async()=>{if(busy)return;if(!alive())throw Error('O projeto mudou; reabra o diagnóstico.');busy=true;d.setAttribute('aria-busy','true');error.textContent='';try{await fn()}catch(e){if(d.isConnected)error.textContent=e.message;else msg(e.message,true)}finally{busy=false;d.setAttribute('aria-busy','false')}},text);row.append(b);return b}
 async function calculate(kind){busy=true;d.close();try{const result=await start(kind);if(!alive())return;if(!result||result.state!=='done')error.textContent=result?.error||result?.message||'A atualização não concluiu. Confira as orientações.';await read()}finally{busy=false;if(alive())d.showModal()}}
 button('Atualizar diagnóstico das rotas',()=>calculate('analyze'));
 const focus=button('Ativar veículos e gerar prévia de tráfego',async()=>{
  if(!data?.itineraries)return;const original=collect();
  $('traffic').checked=true;$('camera_mode').value='trafego';$('view_width_m').value='350';$('preview_mode').value='video';$('preview_time_s').value=String(Math.max(0,Math.min(Number($('duration_s').value)/2,5)));
  try{await save()}catch(e){fill(original);throw e}
  await calculate('preview');
 });
 button('Escolher eixo e configurar faixas',()=>{d.close();d.remove();return RodoviaSections.chooseAxis()});
 button('Corrigir problemas dos fluxos',()=>{d.close();d.remove();return RodoviaExecution.open()});
 button('Configuração do vídeo',()=>{d.close();d.remove();return psOpenHub('video')});
 const close=button('Fechar',()=>{d.close();d.remove()});d.oncancel=e=>{e.preventDefault();if(!busy)close.click()};d.showModal();try{await read()}catch(e){error.textContent=e.message}
}

async function open(){
 requireProject();if(!await RodoviaPanels.close())return;
 const baseline=collect(),rules=structuredClone(M.connection_rules||[]),routes=structuredClone(M.route_alignments||[]);
 const problems=(editor?.segments||[]).filter(s=>!s.disabled&&s.technical_exclusion!=='length_limit'&&/sem itinerário/i.test(s.technical_message||'')&&s.origin_key&&s.mid).slice(0,200);
 const roles={automatico:'Automático existente',principal:'Principal',acesso:'Acesso',retorno:'Retorno',dispositivo:'Dispositivo',rotatoria:'Rotatória'},ends={automatico:'Automático existente',entrada:'Entrada',saida:'Saída',conexao:'Conexão com outro eixo',fim:'Fim de percurso (encerra)' },directions={automatico:'Pelos nós / seção existente',crescente:'Crescente',decrescente:'Decrescente',ambos:'Ambos pela seção'},rotations={cadastro:'Sentido cadastrado',horario:'Horário',anti_horario:'Anti-horário'};
 const select=(name,i,choices,value)=>`<select data-node-field="${name}" data-route-index="${i}">${Object.entries(choices).map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
 const html=`<p>Aplicar preserva o motor normal ou o modo clássico selecionado. O modo clássico é ilustrativo e verifica somente canteiros. As caixas são independentes. Somente rotas não desliga semáforos, interdições ou proteções. Uma verificação desativada identifica a saída como ensaio, sem afirmar ausência de colisões.</p>
 <fieldset><legend>Simulação e proteção</legend>${Object.entries(controls).map(([key,[label,def]])=>`<label><input type="checkbox" data-policy="${key}" ${baseline[key]??def?'checked':''}> ${esc(label)}</label>`).join('')}<p>O seguimento longitudinal, as pessoas e as barreiras físicas continuam protegidos. A caixa de colisões controla a reserva poligonal entre veículos.</p></fieldset>
 <fieldset><legend>Frota</legend><label>Dimensões dos veículos<select data-fleet><option value="variado" ${baseline.vehicle_mix==='variado'?'selected':''}>Variada existente</option><option value="classico" ${baseline.vehicle_mix==='classico'?'selected':''}>Clássica existente</option><option value="engenharia" ${baseline.vehicle_mix==='engenharia'?'selected':''}>Engenharia: leves 2×6 m, motos 0,5×2 m, pesados 3×18 m e longos 3×30 m</option></select></label><p>Longos de 30 m usam envelope rígido conservador; não é um modelo articulado homologado. A frota dos projetos existentes é preservada.</p></fieldset><fieldset><legend>Entrada e demanda</legend><div class="grid">${Object.entries(nums).map(([key,[label,def,min,max]])=>`<label>${esc(label)}<input type="number" step="any" min="${min}" max="${max}" data-number="${key}" value="${baseline[key]??def}"></label>`).join('')}<label>VDM do conjunto de entradas (opcional)<input type="number" min="1" max="1000000" data-vdm value="${baseline.traffic_vdm??''}"></label></div><p>VDM × fração horária gera a demanda da hora; a parcela direcional é repartida entre as entradas desse sentido. Vazio mantém densidade ou demanda horária já configurada. Não é classificação DNIT/CONTRAN.</p></fieldset>
 <details><summary>Eixos, nós e giro das rotatórias</summary><p>A = início geométrico do eixo; B = fim. Entrada → saída orienta o percurso; conexão não cria entrada externa. Acessos recebem 5% por categoria; retornos, dispositivos e rotatórias compartilham 20%. Sem classificação, preserva-se o funcionamento existente. Acesso usa o eixo; demais ramais ficam à direita de seu sentido. As seções continuam definindo larguras e faixas habilitadas.</p>${routes.map((r,i)=>`<fieldset><legend>${esc(r.name)}</legend><div class="grid"><label>Classificação${select('flow_role',i,roles,r.flow_role||'automatico')}</label><label>Nó A${select('flow_start',i,ends,r.flow_start||'automatico')}</label><label>Nó B${select('flow_end',i,ends,r.flow_end||'automatico')}</label><label>Sentido${select('flow_direction',i,directions,r.flow_direction||'automatico')}</label><label>Giro (somente rotatória fechada)${select('roundabout_rotation',i,rotations,r.roundabout_rotation||'cadastro')}</label><label>Entrada externa (veículos/h)<input type="number" min="1" max="1000000" data-external="external_demand_vph" data-route-index="${i}" value="${r.external_demand_vph??''}"></label><label>Ou VDM externo<input type="number" min="1" max="1000000" data-external="external_vdm" data-route-index="${i}" value="${r.external_vdm??''}"></label></div></fieldset>`).join('')||'<p>Selecione um eixo do desenho e configure suas faixas para cadastrá-lo aqui. Não se deduz a função de um eixo apenas pelo nome da camada.</p>'}<p>Percentuais manuais de ligações prevalecem sobre o padrão 5/20. Os percentuais são escolhas de movimento, não criação de veículos. Demanda externa exige nó de entrada e soma ao tráfego principal. Conexão incompleta não fabrica passagem; barreiras, níveis e interdições continuam valendo.</p></details>
 <details open><summary>Conexões e parcelas dos ramais</summary><p>Use a ferramenta de ligação para indicar chegada e saída; somente movimentos geometricamente válidos são aceitos. Os veículos recebidos compartilham a ocupação da via e cedem passagem na incorporação.</p>${rules.map((r,i)=>`<div class="row"><span>${esc(r.name)}</span>${r.action==='force'?`<label>Parcela desta saída (%)<input data-rule="${i}" type="number" min="0" max="100" placeholder="Padrão ${baseline.traffic_branch_share_pct??20}%" value="${r.share_pct??''}"></label>`:'<span>Movimento proibido</span>'}<label><input data-rule-enabled="${i}" type="checkbox" ${r.enabled!==false?'checked':''}> Ativa</label></div>`).join('')||'<p>Nenhuma ligação manual cadastrada. Feche esta janela e use Criar ligação de ramal no menu Tráfego.</p>'}</details>
 <details><summary>OAE e cotas</summary><p>Contornos de OAE em Z=0 não são barreiras. Travessias em níveis diferentes exigem cota relativa confirmada no cadastro da OAE; uma cota CAD absoluta não basta.</p>${(editor?.oae_traffic||[]).map(o=>`<p>${esc(o.id)} · ${o.z_m===null?'cota inválida':'Z='+esc(String(o.z_m))+' m'} · ${o.grade_separation_known?'desnível confirmado':o.transverse?'travessia transversal: conferir cota':'cota sem confirmação de desnível'}</p>`).join('')||'<p>Nenhuma OAE no diagnóstico atual.</p>'}</details>
 <details><summary>Autorização individual de eixos sem pavimento</summary><p>Confirme apenas o alinhamento cuja seção foi conferida. O corredor usa as larguras das faixas e preserva canteiros e barreiras; não libera toda a área do projeto. Para eixo DXF, use Escolher eixo e configurar faixas primeiro.</p>${routes.map((r,i)=>`<label><input type="checkbox" data-outside="${i}" ${r.outside_pavement?'checked':''}> ${esc(r.name)} — autorizar corredor da seção sem hachura de pavimento</label>`).join('')||'<p>Nenhum alinhamento editável cadastrado.</p>'}</details>
 <details><summary>Excluir segmentos desconectados da circulação</summary><p>Apenas os trechos selecionados recebem desligamento persistente. O desenho original é preservado, com possibilidade de desfazer. Atualize o diagnóstico antes de selecionar.</p>${problems.map((s,i)=>`<label><input type="checkbox" data-disconnected="${i}"> ${esc(s.source||'Fluxo '+s.id)} — ${esc(s.technical_message)}</label>`).join('')||'<p>Nenhum segmento desconectado identificado no diagnóstico carregado.</p>'}</details>`;
 const persist=save;let d;
 d=RodoviaModelDialog.open({id:'rsFlowPolicy',title:'Regras e operação dos fluxos',html,calculate:true,save:async()=>{
  if(!d.rsContext())throw Error('O projeto mudou. Reabra a janela.');
  const values={traffic_model:'simulado',vehicle_mix:d.querySelector('[data-fleet]').value};for(const key of Object.keys(controls))values[key]=d.querySelector(`[data-policy=${key}]`).checked;
  for(const [key,[label,def,min,max]] of Object.entries(nums))values[key]=RodoviaModelDialog.number(d.querySelector(`[data-number=${key}]`),label,min,max);
  const raw=d.querySelector('[data-vdm]').value.trim();values.traffic_vdm=raw===''?null:RodoviaModelDialog.number(d.querySelector('[data-vdm]'),'VDM',1,1000000);
  for(const [i,r] of rules.entries()){r.enabled=d.querySelector(`[data-rule-enabled="${i}"]`).checked;if(r.action==='force'){const input=d.querySelector(`[data-rule="${i}"]`);r.share_pct=input.value.trim()===''?null:RodoviaModelDialog.number(input,'Percentual do ramal',0,100)}}
  for(const input of d.querySelectorAll('[data-node-field]'))routes[Number(input.dataset.routeIndex)][input.dataset.nodeField]=input.value;
  for(const input of d.querySelectorAll('[data-external]'))routes[Number(input.dataset.routeIndex)][input.dataset.external]=input.value.trim()===''?null:RodoviaModelDialog.number(input,'Demanda externa',1,1000000);
  for(const [i,r] of routes.entries())r.outside_pavement=d.querySelector(`[data-outside="${i}"]`).checked;
  const removed=[...d.querySelectorAll('[data-disconnected]:checked')].map(e=>problems[Number(e.dataset.disconnected)]);
  if(removed.length&&(window.RodoviaFlowStudy?.stale||projectSession.artifacts.editor?.state!=='ready'))throw Error('O diagnóstico está desatualizado. Atualize os fluxos antes de excluir segmentos.');
  if(removed.length&&!await confirmRemoval(removed.length))return false;
  const previewTime=$('preview_time_s').value;
  const previous=structuredClone(cfg),demand=$('traffic_demand_vphpl').value,fleet=$('vehicle_mix').value,model=$('traffic_model').value;
  checkpoint();M.connection_rules=rules;M.route_alignments=routes;
  for(const s of removed){if(!(M.flow_overrides||[]).some(o=>o.action==='disable'&&o.target_key===s.origin_key))M.flow_overrides.push({id:uid(),x:s.mid[0],y:s.mid[1],target_key:s.origin_key,action:'disable',enabled:true})}
  Object.assign(cfg,values);if(values.traffic_route_only&&!baseline.traffic_route_only)$('preview_time_s').value='0';$('vehicle_mix').value=values.vehicle_mix;$('traffic_model').value='simulado';if(values.traffic_vdm!==null)$('traffic_demand_vphpl').value='';projectSession.epoch++;
  try{await persist();refreshLists();draw();demandInfo()}catch(e){cfg=previous;$('preview_time_s').value=previewTime;$('traffic_demand_vphpl').value=demand;$('vehicle_mix').value=fleet;$('traffic_model').value=model;throw e}
 }});return d;
}

